Change(genesis='e30427e699992327267add669c3bc989f6d16525ba6f493121eec7778638e0ce', deps=(), event=Authored(todo='contextcostflake', at=datetime(2026, 11, 28, 17, 34, 20, 887016), actor='bmabsout', kind='todo', created=datetime(2026, 11, 28, 0, 0, 0), body='The law that a context costs what the store holds, and not its square, holds on a loaded machine and in a debug build', spec=Flat(value=0.6), rationale=('A law that fails by the machine it runs on teaches people to rerun it,', 'and then it guards nothing.'), category='', waiting_on='', detail="The test `context_cost::the_context_costs_what_the_store_holds_and_not_its_square` compares the CPU time of 1,000 and 4,000 lines and asks for a ratio under 8. Two sessions measured about 8.6 to 10.9 in a debug build, alone and under the gate's parallel load, on a small container. Either the law measures something a machine does not hold steady (then count the work, not the time), or the code is worse than linear at that size (then that is the finding).", source=None, subtodos=(), notes=(), note=''))